import{_ as a,o as t,c as s,ae as n}from"./chunks/framework.1Lna8NcP.js";const y=JSON.parse('{"title":"Security & Encryption","description":"","frontmatter":{},"headers":[],"relativePath":"security.md","filePath":"security.md"}'),r={name:"security.md"};function i(o,e,l,c,p,d){return t(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="security-encryption" tabindex="-1">Security &amp; Encryption <a class="header-anchor" href="#security-encryption" aria-label="Permalink to &quot;Security &amp; Encryption&quot;">​</a></h1><p>Libertas stores everything locally. No data is sent to the cloud, no accounts are linked by default, and the database never leaves your machine — unless you explicitly upload a file or enable Plaid sync.</p><p>This page explains how your data is protected at rest, how encryption keys work, and exactly what Claude can and cannot see when you use the AI chat feature.</p><hr><h2 id="what-gets-encrypted" tabindex="-1">What gets encrypted <a class="header-anchor" href="#what-gets-encrypted" aria-label="Permalink to &quot;What gets encrypted&quot;">​</a></h2><p>All financial text data is encrypted before it&#39;s saved to the database. This includes:</p><ul><li>Account names and external IDs</li><li>Institution names, URLs, and notes</li><li>Transaction descriptions and ticker symbols</li><li>Holdings symbols</li><li>Property addresses</li><li>Settings values (including API keys)</li></ul><p><strong>Not encrypted:</strong> numeric values like balances, amounts, prices, and interest rates. Encrypting numbers would break the charts and dashboards — and raw numbers without names or descriptions reveal very little on their own.</p><hr><h2 id="how-encryption-works" tabindex="-1">How encryption works <a class="header-anchor" href="#how-encryption-works" aria-label="Permalink to &quot;How encryption works&quot;">​</a></h2><p>Libertas uses <strong>AES-256-GCM</strong>, the same cipher used to protect classified government data and secure financial systems. Every field is encrypted individually with a unique random nonce, so identical values produce different ciphertext.</p><p>The database file itself is standard SQLite. If someone steals it, they see a file full of random-looking bytes for all text fields — nothing readable.</p><h3 id="the-encryption-key" tabindex="-1">The encryption key <a class="header-anchor" href="#the-encryption-key" aria-label="Permalink to &quot;The encryption key&quot;">​</a></h3><p>AES-256-GCM requires a 32-byte key. Where that key comes from depends on your security setting:</p><p><strong>macOS Keychain (default)</strong></p><p>A random 32-byte key is generated the first time you run Libertas. macOS stores it in your system Keychain — the same place Safari stores passwords and Apple stores your iCloud credentials. It&#39;s protected by your login password and unlocks automatically with Touch ID on supported hardware.</p><p>When Libertas starts, it retrieves the key from Keychain and holds it in memory. No passphrase required, no extra steps. The key is never written to the database or to any file.</p><p><strong>Passphrase (maximum security)</strong></p><p>If you switch to passphrase mode in Settings → Data Security, Libertas derives the encryption key from your passphrase using <strong>Argon2id</strong> — the current gold standard for password-based key derivation. Argon2id is intentionally slow and memory-intensive, making brute-force attacks impractical.</p><p>A random salt is generated and stored in the database (the salt is not secret — it just ensures the same passphrase produces a unique key for your specific database). The derived key lives only in memory for the duration of the session.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>If you use passphrase mode and lose your passphrase, the data <strong>cannot be recovered</strong>. There is no backdoor, no recovery key, no support ticket that can help. This is a feature, not a limitation — it means no one else can access your data either.</p></div><hr><h2 id="when-data-is-decrypted" tabindex="-1">When data is decrypted <a class="header-anchor" href="#when-data-is-decrypted" aria-label="Permalink to &quot;When data is decrypted&quot;">​</a></h2><p>Decryption happens in memory, on demand, when:</p><ol><li>The app loads a page that reads from the database</li><li>You run a search or filter</li><li>Claude analyzes your data (see below)</li></ol><p>Decrypted data is never written back to disk. It exists in RAM for the duration of the request, then is discarded.</p><hr><h2 id="how-claude-interacts-with-your-data" tabindex="-1">How Claude interacts with your data <a class="header-anchor" href="#how-claude-interacts-with-your-data" aria-label="Permalink to &quot;How Claude interacts with your data&quot;">​</a></h2><p>When you use the AI chat or ask for AI-powered insights, here&#39;s exactly what happens:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Your question</span></span>
<span class="line"><span>     ↓</span></span>
<span class="line"><span>Libertas queries the database</span></span>
<span class="line"><span>     ↓</span></span>
<span class="line"><span>SQLAlchemy decrypts matching rows in memory</span></span>
<span class="line"><span>     ↓</span></span>
<span class="line"><span>Decrypted results are formatted as context</span></span>
<span class="line"><span>     ↓</span></span>
<span class="line"><span>Context + your question → Claude API (HTTPS/TLS 1.3)</span></span>
<span class="line"><span>     ↓</span></span>
<span class="line"><span>Claude analyzes and responds</span></span>
<span class="line"><span>     ↓</span></span>
<span class="line"><span>Response displayed in app</span></span></code></pre></div><p><strong>Claude never:</strong></p><ul><li>Touches the database file</li><li>Receives encrypted ciphertext</li><li>Stores or remembers your data between sessions</li><li>Has access to your encryption key</li></ul><p><strong>Claude only receives:</strong></p><ul><li>The specific rows needed to answer your question (e.g., last 3 months of transactions for a spending question)</li><li>Your question</li><li>Any context you explicitly provide</li></ul><p>API calls to Claude are encrypted in transit with TLS 1.3. Anthropic&#39;s data retention policy applies to the content of API calls — review it at <a href="https://anthropic.com/privacy" target="_blank" rel="noreferrer">anthropic.com/privacy</a> if this matters to your threat model.</p><hr><h2 id="changing-your-security-mode" tabindex="-1">Changing your security mode <a class="header-anchor" href="#changing-your-security-mode" aria-label="Permalink to &quot;Changing your security mode&quot;">​</a></h2><p>Go to <strong>Settings → Data Security</strong> to switch between modes. When you switch to macOS Keychain mode, the key is initialized immediately. When you switch to Passphrase mode, you&#39;ll set your passphrase there — existing data will be re-encrypted on the next write using your new key.</p><hr><h2 id="technical-reference" tabindex="-1">Technical reference <a class="header-anchor" href="#technical-reference" aria-label="Permalink to &quot;Technical reference&quot;">​</a></h2><ul><li>Cipher: AES-256-GCM (authenticated encryption — detects tampering)</li><li>Key derivation (passphrase mode): Argon2id, 3 iterations, 64 MB memory, 4 threads, 32-byte output</li><li>Keychain integration: Python <code>keyring</code> library → macOS Security framework</li><li>Encrypted value format: <code>enc1:</code> prefix + base64(12-byte nonce + ciphertext + 16-byte GCM tag)</li><li>Implementation: <code>backend/services/encryption.py</code>, <code>backend/models.py</code> (<code>EncryptedText</code> TypeDecorator)</li><li>ADR: <a href="/Libertas/adr/010-at-rest-encryption.html">ADR-010 — At-Rest Encryption</a></li></ul>`,41)])])}const u=a(r,[["render",i]]);export{y as __pageData,u as default};
